 const mapped=s.groups.reduce((n,g)=>n+g.points.length,0);$('map-caption').textContent=`${num(mapped)} selected LIBS measurements at ${num(s.groups.length)} sampled rover locations. Colour: ${key==='oxide'?'median '+api.label(s.oxide)+' estimate':'median derived '+METRICS[key].name}. ${num(events.length)} enabled, geolocated evidence records are independent of the LIBS filters. White route joins sampled locations; it is not the full navigation path.`;
