function chartFrame(canvas,xmin,xmax,ymin,ymax,xlabel,ylabel){const {ctx,w,h}=setup(canvas),p=palette();ctx.fillStyle=p.plot;ctx.fillRect(0,0,w,h);const left=61,right=22,top=27,bottom=52,pw=w-left-right,ph=h-top-bottom,xp=v=>left+(v-xmin)/(xmax-xmin||1)*pw,yp=v=>top+ph-(v-ymin)/(ymax-ymin||1)*ph;ctx.font='10px ui-monospace,monospace';for(let i=0;i<5;i++){const yy=ymin+(ymax-ymin)*i/4,y=yp(yy);ctx.strokeStyle=p.line;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle=p.muted;ctx.textAlign='right';ctx.fillText(Math.abs(yy)<.01&&yy!==0?yy.toExponential(1):fmt(yy,Math.abs(ymax-ymin)<2?3:1),left-8,y+3);}for(let i=0;i<5;i++){const xx=xmin+(xmax-xmin)*i/4;ctx.fillStyle=p.muted;ctx.textAlign='center';ctx.fillText(fmt(xx,xmax-xmin<10?1:0),xp(xx),h-29);}ctx.fillStyle=p.muted;ctx.textAlign='center';ctx.fillText(xlabel,left+pw/2,h-7);ctx.save();ctx.translate(13,top+ph/2);ctx.rotate(-Math.PI/2);ctx.fillText(ylabel,0,0);ctx.restore();return{ctx,w,h,xp,yp,left,right,top,bottom,pw,ph,p};}
